insert into public.lessons (id, module_id, slug, title, description, learn_excerpt, sort_order, is_published) values ('d1000001-0001-4001-8001-000001000001', 'e1000001-0001-4001-8001-000000000001', 'vowels-nasals', 'Nasal vowels and rhythm', NULL, 'Portuguese uses nasal vowels (ã, õ, -m, -n) that change meaning. Keep the jaw relaxed and let air pass through the nose without pinching.', 1, true);
