insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000001', 'f0000002-0002-4002-8002-000000000002', 'nasal-vowels', 'Nasal vowels', 'ã, õ, and nasal -m/-n endings shape meaning in European Portuguese.', '{"explanation": "Nasality comes from lowering the soft palate so air exits nose and mouth together.", "englishApproximation": "Think of French nasal vowels, but keep the mouth a bit more open for Portuguese.", "mouthPosition": "Jaw relaxed; tongue forward for ã; avoid pinching the nose.", "commonMistakes": "Turning every final -n into a hard English n instead of nasalizing the vowel.", "exampleWords": ["pão", "irmã", "bem", "bom"], "examplePhrases": ["Bom dia", "Bem vindo", "Pão de centeio"]}'::jsonb, 1);
insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000002', 'f0000002-0002-4002-8002-000000000002', 'final-s-sh', 'Final -s as “sh” (European Portuguese)', 'Between vowels or at end of word in many accents, -s can sound like sh.', '{"explanation": "In connected speech, plural -s often softens in central/northern European Portuguese patterns.", "englishApproximation": "Not always as strong as English sh—often lighter.", "mouthPosition": "Tip of tongue down; air flows forward.", "commonMistakes": "Using a hard American s everywhere.", "exampleWords": ["amigos", "estás"], "examplePhrases": ["Bom dias", "Os amigos"]}'::jsonb, 2);
insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000003', 'f0000002-0002-4002-8002-000000000002', 'unstressed-vowels', 'Unstressed vowels', 'Unstressed vowels stay clearer than in English, but avoid over-pronouncing.', '{"explanation": "European Portuguese reduces some vowels, but beginners should start clear then refine with listening.", "englishApproximation": "Keep e and o from collapsing into uh too early.", "mouthPosition": "Small mouth movements between syllables.", "commonMistakes": "Mumbling every unstressed vowel into schwa.", "exampleWords": ["meseta", "porta"], "examplePhrases": ["Obrigado pela ajuda"]}'::jsonb, 3);
insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000004', 'f0000002-0002-4002-8002-000000000002', 'open-closed-vowels', 'Open vs closed vowels', 'Pairs like a/á and o/ó change quality — listen more than you memorize rules at first.', '{"explanation": "Vowel height affects meaning in some minimal pairs; use slow listening first.", "englishApproximation": "Open o is closer to awe; closed o is closer to oh.", "mouthPosition": "Open: jaw drops; closed: smaller opening.", "commonMistakes": "Using English oh for every Portuguese o.", "exampleWords": ["avó", "avô"], "examplePhrases": ["Olá, tudo bem?"]}'::jsonb, 4);
insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000005', 'f0000002-0002-4002-8002-000000000002', 'portuguese-r', 'Portuguese R', 'Single flap and double rr contrast; keep it light, not American growl.', '{"explanation": "Tap the tongue once for single r between vowels; stronger for rr.", "englishApproximation": "Single r can feel like a soft American d in rider.", "mouthPosition": "Tip near alveolar ridge; quick tap.", "commonMistakes": "American hard R at ends of words like English car.", "exampleWords": ["carro", "para"], "examplePhrases": ["Por favor"]}'::jsonb, 5);
insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000006', 'f0000002-0002-4002-8002-000000000002', 'lh-nh', 'LH and NH', 'lh like ly in million (roughly); nh like ny in canyon.', '{"explanation": "Palatal consonants link smoothly to following vowels.", "englishApproximation": "nh ≈ Spanish ñ; lh is a lateral palatal approximant.", "mouthPosition": "Middle of tongue toward palate for nh; sides of tongue for lh.", "commonMistakes": "Pronouncing nh as n + h separately.", "exampleWords": ["telhado", "amanhã"], "examplePhrases": ["Boa noite"]}'::jsonb, 6);
insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000007', 'f0000002-0002-4002-8002-000000000002', 'word-stress', 'Word stress', 'Stress often falls on one of the last three syllables—patterns exist, but listen first.', '{"explanation": "Accent marks show stress when it breaks the default pattern.", "englishApproximation": "Avoid English habit of stressing early syllables in Portuguese words.", "mouthPosition": "Slightly lengthen stressed vowel; keep others clear.", "commonMistakes": "Stressing the first syllable of every word.", "exampleWords": ["café", "útil"], "examplePhrases": ["Obrigado"]}'::jsonb, 7);
insert into public.sound_lessons (id, course_id, slug, title, summary, body, sort_order) values ('c1000001-0001-4001-8001-000000000008', 'f0000002-0002-4002-8002-000000000002', 'sentence-rhythm', 'Sentence rhythm', 'European Portuguese can feel faster—chunk phrases, do not translate word by word aloud.', '{"explanation": "Group function words with content words in practice chunks.", "englishApproximation": "Short breath groups like mini-phrases.", "mouthPosition": "Steady airflow; avoid stopping between every word.", "commonMistakes": "Adding English filler rhythm and pauses.", "exampleWords": [], "examplePhrases": ["Um café, por favor", "Onde fica o metro?"]}'::jsonb, 8);
